import io.heapy.kotdoc.crypto.*;import kotlin.*;import java.math.BigInteger;
class RsaQLoopReview {static int calls=0;static class G implements CryptoDrg<G>{int i;G(int n){i=n;}public Pair<byte[],G> randomBytesGenerate(int n){throw new AssertionError();}}
public static void main(String[] a){var rsa=new CryptoRsa(new CryptoNumberPrime(new CryptoProbabilistic(n->new byte[n])));CryptoDrgOperations<G> ops=(n,g)->{int i=g.getValue().i;if(++calls>5000)throw new IllegalStateException("budget");byte[] b=new byte[n];java.util.Arrays.fill(b,(byte)0);return new Pair<>(LazyKt.lazyOf(b),LazyKt.lazyOf(new G(i+1)));};try{var action=rsa.generateAction(LazyKt.lazyOf(2),LazyKt.lazyOf(BigInteger.valueOf(17)),ops);CryptoRandom.INSTANCE.withDRG(new G(0),action).getFirst().getValue();System.out.println("returned");}catch(Throwable e){System.out.println(e.getClass().getSimpleName()+":"+e.getMessage()+" calls="+calls);}}}
